-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- metoprolol (CIS 68743715)
  m := pg_temp.jp_matrice_by_norm('metoprolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : bétabloquant sélectif - code ATC : C07AB02');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Dans la prise en charge de :', 'Hypertension artérielle', 'Angine de poitrine', 'Troubles du rythme cardiaque (en particulier tachycardies supraventriculaires)', 'Traitement adjuvant de la thyrotoxicose', 'L’infarctus du myocarde aigu : l’intervention précoce du tartrate de métoprolol réduit la taille de l’infarctus et l’incidence de la fibrillation ventriculaire.', 'Le soulagement de la douleur peut également réduire le besoin d’analgésiques opiacés', 'Traitement au long court après la récupération d’un infarctus aigu du myocarde', 'Prophylaxie de la migraine', 'Il a été démontré que le tartrate de métoprolol réduit la mortalité lorsqu’il est administré à des patients victimes d’un infarctus du myocarde.', 'Le métoprolol est indiqué chez l’adulte.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au métoprolol, dérivés apparentés, tout autres bétabloquants ou à l’un des excipients mentionnés à la rubrique 6.1', 'Bloc atrio-ventriculaire du second ou troisième degré', 'Patients avec une insuffisance cardiaque non contrôlée', 'Bradycardie sinusale cliniquement pertinente (', 'Syndrome du sinus malade (sauf pacemaker)', 'Angor de Prinzmetal', 'Infarctus du myocarde compliqué par bradycardie significative, BAV du 1er degré, hypotension systolique (', 'Trouble périphériques artériels périphériques', 'Asthme et antécédents de bronchospasme', 'Phéochromocytome non traité', 'Acidose métabolique', 'Administration intraveineuse concomitante d’inhibiteurs calciques, de type vérapamil ou diltiazem ou autres anti-arythmiques (comme le disopyramide) est contre-indiqué (hors soins intensifs)']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’arrêt brutal d’un traitement par un bêta‑bloquant doit être évité, en particulier chez les patients atteints de cardiopathie ischémique.', 'Lorsque cela est possible, le métoprolol doit être arrêté progressivement sur une période de 10 jours, les doses diminuant jusqu’à 25 mg durant les 6 derniers jours.', 'Si nécessaire, un traitement de substitution doit être instauré simultanément afin de prévenir une exacerbation de l’angor.', 'De plus, une hypertension et des arythmies peuvent apparaître.', 'Lorsque l’interruption d’un bêta‑bloquant est décidée en préparation d’une intervention chirurgicale, le traitement doit être arrêté au moins 24 heures avant.', 'La poursuite du traitement bêta‑bloquant réduit le risque d’arythmies lors de l’induction et de l’intubation, mais peut également augmenter le risque d’hypertension.', 'Si le traitement est poursuivi, certaines précautions doivent être prises avec l’utilisation de certains anesthésiques.', 'Le patient peut être protégé contre les réactions vagales par l’administration intraveineuse d’atropine.', 'Pendant la période de sevrage, le patient doit être étroitement surveillé.', 'Bien que le métoprolol se soit révélé sûr chez un grand nombre de patients asthmatiques, il est recommandé de faire preuve de prudence chez les patients souffrant de bronchopneumopathie chronique obstructive.', 'Un traitement par un bêta-2‑stimulant peut devenir nécessaire ou un traitement en cours peut nécessiter un ajustement.', 'Par conséquent, les bêta‑bloquants non sélectifs ne doivent pas être utilisés chez ces patients, et les bêta-1‑sélectifs seulement avec une extrême précaution.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Les anesthésiques peuvent atténuer la tachycardie réflexe et augmenter le risque d’hypotension.', 'Le traitement par métoprolol doit être signalé à l’anesthésiste avant l’administration d’un anesthésique général.', 'Si possible, l’arrêt du métoprolol doit être effectué au moins 48 heures avant l’anesthésie.', 'Cependant, pour certains patients subissant une intervention chirurgicale programmée, il peut être souhaitable d’utiliser un bêta‑bloquant en prémédication.', 'Les anesthésiques provoquant une dépression myocardique, tels que le cyclopropane et le trichloroéthylène, doivent être évités.', 'Chez un patient sous bêta‑blocage, un anesthésique ayant une activité inotrope négative aussi faible que possible (halothane/protoxyde d’azote) doit être choisi.', 'Il peut être nécessaire d’ajuster la dose de l’agent hypoglycémiant chez les patients atteints de diabète instable ou insulinodépendant.', 'Le blocage bêta‑adrénergique peut empêcher l’apparition de signes d’hypoglycémie (comme la tachycardie).', 'L’utilisation concomitante de bêta-bloquants avec des sulfamides hypoglycémiants peut augmenter le risque d’hypoglycémie sévère (voir rubrique 4.4).', 'Toutefois, des associations d’antihypertenseurs peuvent souvent être utilisées avec bénéfice pour améliorer le contrôle de l’hypertension.', 'Les inhibiteurs calciques de type vérapamil ne doivent pas être administrés par voie intraveineuse aux patients recevant des bêta‑bloquants (voir rubrique 4.3).', 'Il convient également de prendre des précautions lorsque les bêta‑bloquants sont administrés avec des agents bloquant les ganglions sympathiques, d’autres bêta‑bloquants ou des inhibiteurs de la MAO.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences estimées : très fréquent (≥ 1/10), fréquent (≥ 1/100,', 'Très fréquent', '(> 1/10)', 'Fréquent', '(≥ 1/100 à', 'Peu fréquent', '(≥ 1/10 000 à']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Pendant la période de sevrage, le patient doit être étroitement surveillé.']);

  -- nebivolol (CIS 67856966)
  m := pg_temp.jp_matrice_by_norm('nebivolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmaco-thérapeutique: BETA-BLOQUANT, SELECTIF, Code ATC: C07AB12.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension', 'Traitement de l''hypertension artérielle essentielle.', 'Insuffisance cardiaque chronique', 'Traitement de l''insuffisance cardiaque chronique stable, légère et modérée, en association aux traitements conventionnels chez des patients âgés de 70 ans ou plus.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance hépatique ou altération de la fonction hépatique.', 'Insuffisance cardiaque aiguë, choc cardiogénique ou épisodes de décompensation de l''insuffisance cardiaque nécessitant un traitement inotrope intraveineux.', 'De plus, comme pour d''autres bêta-bloquants, NEBIVOLOL ALMUS est contre-indiqué dans les cas suivants :', 'maladie du sinus incluant bloc sino-auriculaire,', 'blocs auriculo-ventriculaires des second et troisième degrés (non appareillés),', 'antécédents de bronchospasme et d''asthme bronchique,', 'phéochromocytome non traité,', 'acidose métabolique,', 'bradycardie (fréquence cardiaque', 'hypotension (pression artérielle systolique', 'troubles circulatoires périphériques dans leurs formes sévères.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Les mises en garde et précautions suivantes sont communes aux bêta-bloquants:', 'Anesthésie générale', 'La poursuite du traitement par bêta-bloquant diminue le risque d''arythmie pendant l''induction et l''intubation.', 'Si le traitement par bêta-bloquant est arrêté en vue d''une intervention, il sera suspendu pour au moins 24 heures avant.', 'Il convient d''observer une prudence particulière avec certains anesthésiques dépresseurs myocardiques.', 'Le patient peut être protégé d''une prédominance vagale par l''administration d''atropine par voie intraveineuse.', 'Cardiovasculaires', 'Généralement, les bêta-bloquants ne doivent pas être utilisés chez les patients présentant une insuffisance cardiaque congestive non traitée, à moins qu''elle ne soit stabilisée.', 'Chez les patients présentant une cardiopathie ischémique, le traitement par bêta-bloquant devra être diminué progressivement c''est-à-dire sur 1 à 2 semaines.', 'Si nécessaire, un traitement substitutif devra être commencé en même temps pour éviter une aggravation de l''angor.', 'Les bêta-bloquants doivent être administrés avec prudence:', 'chez les patients souffrant de troubles circulatoires périphériques (maladie ou syndrome de Raynaud, claudication intermittente), une aggravation de ces troubles pouvant apparaître,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions pharmacodynamiques', 'Les interactions suivantes sont communes aux bêta-bloquants:', 'Associations déconseillées', '+ Anti-arythmiques de classe I (quinidine, hydroquinidine, cibenzoline, flecaïnide, disopyramide, lidocaïne, mexilétine, propafénone)', 'Potentialisation de l''effet sur le temps de conduction auriculo-ventriculaire et augmentation de l''effet inotrope négatif (voir rubrique 4.4).', '+ Antagonistes calciques du type vérapamil ou diltiazem', 'Effet négatif sur la contractilité et la conduction auriculo-ventriculaire.', 'L''administration de vérapamil par voie IV chez les patients traités par bêta-bloquants peut induire une hypotension sévère et un bloc auriculo-ventriculaire (voir rubrique 4.4).', '+ Anti-hypertenseurs d''action centrale (clonidine, guanfacine, moxonidine, méthyldopa, rilménidine)', 'Il existe un risque accru d''« hypertension rebond » en cas d''arrêt brutal du traitement par anti-hypertenseur central, en particulier s''il a lieu avant l''arrêt du bêta-bloquant.', 'Associations faisant l''objet de précautions d’emploi', '+ Anti-arythmiques de classe III (amiodarone)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent (1/100 à 1/10)', 'Peu fréquent (1/1000 à 1/100)', 'Très rare (≤ 1/10000)']);

  -- atorvastatine (CIS 61411404)
  m := pg_temp.jp_matrice_by_norm('atorvastatine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Hypolipidémiants, inhibiteurs de l''HMG-CoA réductase, Code ATC: C10AA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypercholestérolémie', 'Prévention des maladies cardiovasculaires']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['ATORVASTATINE ACCORD est contre-indiqué chez les patients:', 'présentant une hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'atteints d''une affection hépatique évolutive ou ayant des élévations persistantes et inexpliquées des transaminases sériques supérieure à trois fois la limite supérieure de la normale.', 'chez les femmes enceintes, allaitantes ou en âge de procréer et n''utilisant pas de méthodes contraceptives fiables (voir rubrique 4.6).', 'traités avec les agents antiviraux contre l’hépatite C glécaprévir/pibrentasvir.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Dans quelques cas, il a été rapporté que les statines induisaient de novo ou aggravaient une myasthénie préexistante ou une myasthénie oculaire (voir rubrique 4.8).', 'ATORVASTATINE ACCORD doit être arrêté en cas d’aggravation des symptômes.', 'Des récurrences ont été rapportées lorsque la même statine ou une statine différente a été (ré)administrée.', 'Effets hépatiques', 'Des épreuves fonctionnelles hépatiques doivent être réalisées avant le début du traitement, lors de l''adaptation posologique puis régulièrement après l''instauration de celui-ci.', 'Des tests fonctionnels hépatiques doivent être réalisés chez les patients développant des signes ou symptômes évoquant une altération hépatique.', 'En cas d''élévation du taux sérique des transaminases, une surveillance s''impose jusqu''à normalisation.', 'En cas d''augmentation persistante des transaminases dépassant 3 fois la limite supérieure de la normale (LSN), la posologie devra être diminuée ou ATORVASTATINE ACCORD devra être arrêté (voir rubrique 4.8).', 'ATORVASTATINE ACCORD doit être utilisé avec prudence chez les patients consommant des quantités importantes d''alcool et/ou ayant des antécédents d''affection hépatique.', 'Prévention des AVC par diminution agressive des taux de cholestérol (Etude SPARCL)', 'Ce risque élevé est particulièrement observé chez des patients ayant déjà fait un AVC hémorragique ou un infarctus lacunaire à l''inclusion de l''étude.', 'Chez les patients ayant un antécédent d''AVC hémorragique ou d''infarctus lacunaire, la balance bénéfice/risque de l''atorvastatine 80 mg est incertaine.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Effet des médicaments co-administrés sur l’atorvastatine', 'L’atorvastatine est métabolisée par le cytochrome P450 3A4 (CYP3A4) et est un substrat des transporteurs hépatiques, polypeptides transporteurs d’anions organiques 1B1 (OATP1B1) et 1B3 (OATP1B3).', 'Les métabolites de l’atorvastatine sont des substrats de l’OATP1B1.', 'L''administration concomitante de médicaments inhibiteurs du CYP3A4 ou des transporteurs protéiques peut augmenter les concentrations plasmatiques d''atorvastatine et à un risque majoré de myopathie.', 'Le risque peut aussi être augmenté lors de l''administration concomitante d''atorvastatine avec d''autres médicaments pouvant induire des myopathies, tels que les fibrates et l''ézétimibe (voir rubrique 4.4).', 'Inhibiteurs du cytochrome CYP3A4', 'Les concentrations plasmatiques d''atorvastatine sont augmentées de façon importante lors de l''association avec les inhibiteurs puissants du CYP3A4 (voir Tableau 1 et les informations spécifiques ci-dessous).', 'Les inhibiteurs modérés du CYP3A4 (tels que érythromycine, diltiazem, vérapamil et le fluconazole) peuvent augmenter les concentrations plasmatiques d''atorvastatine (voir Tableau 1).', 'Une majoration du risque de myopathie a été observée lors de l''administration concomitante d''érythromycine et de statines.', 'Aucune étude d''interaction évaluant les effets de l''amiodarone ou du vérapamil sur l''atorvastatine n''a été réalisée.', 'L''amiodarone et le vérapamil étant tous deux connus pour inhiber l''activité du CYP3A4, leur association avec l''atorvastatine peut entraîner une augmentation de l''exposition à l''atorvastatine.', 'C''est pourquoi, une dose initiale plus faible d''atorvastatine doit être prescrite et une surveillance clinique adéquate du patient doit être mise en place.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences estimées des effets indésirables sont classées selon la convention suivante: fréquent (≥ 1/100, fréquence indéterminée (ne peut être estimée sur la base des données disponibles).', 'Fréquent: rhinopharingite.', 'Rare: thrombocytopénie.', 'Fréquent: réactions allergiques.', 'Très rare: anaphylaxie.', 'Fréquent: hyperglycémie.', 'Peu fréquent: hypoglycémie, prise de poids, anorexie.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En cas d''élévation du taux sérique des transaminases, une surveillance s''impose jusqu''à normalisation.']);

  -- enalapril (CIS 69468186)
  m := pg_temp.jp_matrice_by_norm('enalapril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteurs de l''enzyme de conversion de l''angiotensine, code ATC : C09AA02');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension artérielle.', 'Traitement de l’insuffisance cardiaque symptomatique.', 'Prévention de l’insuffisance cardiaque symptomatique chez des patients ayant une dysfonction ventriculaire gauche asymptomatique (fraction d’éjection ≤ 35 %)', '(Voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, ou à l’un des excipients mentionnés à la rubrique 6.1 ou tout autre IEC.', 'Antécédent d''angio-œdème lié à un traitement antérieur par un IEC.', 'Angio-œdème héréditaire ou idiopathique.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'L’association de ENALAPRIL ACCORD à des médicaments contenant de l''aliskiren est contre-indiquée chez les patients présentant un diabète ou une insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).', 'L’utilisation concomitante avec l’association sacubitril/valsartan.', 'ENALAPRIL ACCORD ne doit pas débuter moins de 36 heures après la dernière dose de l’association sacubitril/valsartan (voir rubriques 4.4 et 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypotension symptomatique', 'Une hypotension symptomatique est rarement observée chez les patients hypertendus non compliqués.', 'Chez les patients ayant une insuffisance cardiaque, associée ou non à une insuffisance rénale, une hypotension symptomatique a été observée.', 'Chez ces patients, le traitement doit être débuté sous surveillance médicale et les patients doivent être suivis étroitement chaque fois que la dose de ENALAPRIL ACCORD et/ou de diurétique est ajustée.', 'Si une hypotension survient, le patient doit être mis en position couchée et, si nécessaire, doit recevoir une perfusion intraveineuse de solution salée isotonique.', 'Chez certains patients insuffisants cardiaques qui ont une pression artérielle normale ou basse, une baisse supplémentaire de la pression artérielle systémique peut survenir avec ENALAPRIL ACCORD.', 'Cet effet est attendu et n''est habituellement pas une raison pour arrêter le traitement.', 'Si l''hypotension devient symptomatique, une réduction de la dose et/ou l''arrêt du diurétique et/ou de ENALAPRIL ACCORD peuvent être nécessaires.', 'Sténose aortique ou mitrale/cardiomyopathie hypertrophique', 'Altération de la fonction rénale', 'Si elle est diagnostiquée rapidement et traitée de façon appropriée, l’insuffisance rénale lorsqu’elle est associée à un traitement avec l’énalapril est habituellement réversible.', 'Une réduction de la dose et/ou l''arrêt du diurétique peuvent être nécessaires.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubrique 4.3 et 4.4).', 'L’utilisation concomitante des IEC avec le racécadotril, les inhibiteurs mTOR (tels que sirolimus, everolimus, temsirolimus) et la vildagliptine peut entrainer un risque accru d’angio-œdème (voir rubrique 4.4).', 'Double blocage du système rénine-angiotensine-aldostérone (SRAA)', 'Diurétiques épargneurs de potassium, suppléments potassiques ou d''autres médicaments susceptibles d''augmenter le taux de potassium sérique', 'Bien que la kaliémie demeure habituellement dans les limites de la normale, une hyperkaliémie peut survenir chez certains patients traités par ENALAPRIL ACCORD.', 'Par conséquent, l’association d’ENALAPRIL ACCORD avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Ciclosporine', 'Une hyperkaliémie peut survenir lors de l’utilisation concomitante d’IEC avec de la ciclosporine.', 'Une surveillance de la kaliémie est recommandée.', 'Héparine']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent', '(≥ 1/10)', 'Fréquent', '(≥ 1/100 et', 'Peu fréquent', '(≥ 1/10 000 et']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Chez ces patients, le traitement doit être débuté sous surveillance médicale et les patients doivent être suivis étroitement chaque fois que la dose de ENALAPRIL ACCORD et/ou de diurétique est ajustée.', 'Altération de la fonction rénale']);

  -- ramipril (CIS 68359312)
  m := pg_temp.jp_matrice_by_norm('ramipril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Ramipril et diurétiques, code ATC : C09BA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension.', 'Cette association à dose fixe est indiquée chez les patients dont la pression artérielle n''est pas adéquatement contrôlée par le ramipril seul ou l''hydrochlorothiazide seul.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['antécédents d’angiœdème (héréditaire, idiopathique ou du fait d''un antécédent d’angiœdème avec les IEC ou les ARA-II) ;', 'utilisation concomitante avec l’association sacubitril/valsartan (voir rubriques 4.4 et 4.5) ;', 'traitements extracorporels impliquant une mise en contact du sang avec des surfaces chargées négativement (voir rubrique 4.5) ;', 'sténose artérielle rénale bilatérale significative, ou sténose artérielle rénale sur rein fonctionnellement unique ;', '2ème et 3ème trimestres de la grossesse (cf. rubriques 4.4 et 4.6) ;', 'allaitement (voir rubrique 4.6) ;', 'insuffisance rénale sévère avec clairance de la créatinine inférieure à 30 ml/min chez un patient non dialysé ;', 'troubles électrolytiques cliniquement significatifs susceptibles de s''aggraver après traitement par RAMIPRIL/HYDROCHLOROTHIAZIDE BIOGARAN (voir rubrique 4.4) ;', 'insuffisance hépatique sévère ;', 'encéphalopathie hépatique ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Grossesse', 'Les IEC tels que le ramipril, ou les antagonistes des récepteurs de l’angiotensine II (ARA II) ne doivent pas être débutés au cours de la grossesse.', 'En cas de diagnostic de grossesse, le traitement par IEC/ARA II doit être arrêté immédiatement et si nécessaire un traitement alternatif sera débuté (voir rubriques 4.3 et 4.6).', 'Populations particulières', 'Patients à risque particulier d’hypotension', 'Patients à système rénine-angiotensine-aldostérone fortement activé', 'Une activation significative du système rénine-angiotensine-aldostérone est à prévoir, et une surveillance médicale, y compris le contrôle de la pression artérielle, est nécessaire par exemple en cas de :', 'o patients ayant une hypertension sévère ;', 'o patients ayant une insuffisance cardiaque congestive décompensée ;', 'o patients ayant une obstruction hémodynamique significative au remplissage ou à l’éjection du ventricule gauche (par ex. une sténose de la valve aortique ou mitrale) ;', 'o patients ayant une sténose artérielle rénale unilatérale avec un second rein fonctionnel ;', 'o patients ayant ou susceptibles de développer une déplétion hydrosodée (y compris les patients sous diurétiques) ;']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'L’utilisation concomitante des IEC avec l’association sacubitril/valsartan est contre-indiquée car elle augmente le risque d’angiœdème (voir rubriques 4.3 et 4.4).', 'Le traitement avec ramipril ne doit pas être débuté moins de 36 heures après la prise de la dernière dose de l’association sacubitril/valsartan.', 'L’association sacubitril/valsartan ne doit pas être débutée moins de 36 heures après la dernière dose de RAMIPRIL/HYDROCHLOROTHIAZIDE BIOGARAN.', 'Si un tel traitement est requis, le recours à un type différent de membrane de dialyse ou à une classe différente d''agents antihypertenseurs doit être envisagé.', 'Associations faisant l''objet de précautions d’emploi', 'Une hyperkaliémie peut survenir, par conséquent, une surveillance étroite du potassium sérique est requise.', 'Une potentialisation du risque d''hypotension est à prévoir (voir rubrique 4.2 concernant les diurétiques).', '+ Sympathomimétiques vasopresseurs et autres substances (épinéphrine) susceptibles de réduire l''effet antihypertenseur du ramipril', 'Une surveillance de la pression artérielle est recommandée.', 'De plus, l’effet des sympathomimétiques vasopresseurs peut être atténué par l’hydrochlorothiazide.', '+ Allopurinol, immunosuppresseurs, corticoïdes, procaïnamide, cytostatiques et autres substances susceptibles de modifier la numération sanguine']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les réactions indésirables graves comprennent un angiœdème ou une réaction anaphylactique, une insuffisance rénale ou hépatique, une pancréatite, des réactions cutanées sévères et une neutropénie/agra', 'Très fréquentes (≥1/10) ; fréquentes (≥ 1/100 à Au sein de chaque groupe de fréquence, les effets indésirables sont présentés par ordre décroissant de gravité.', 'Fréquents', 'Peu fréquents']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une activation significative du système rénine-angiotensine-aldostérone est à prévoir, et une surveillance médicale, y compris le contrôle de la pression artérielle, est nécessaire par exemple en cas de :']);

  -- captopril (CIS 61090375)
  m := pg_temp.jp_matrice_by_norm('captopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’enzyme de conversion non associés, code ATC : C09AA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.', 'Insuffisance cardiaque congestive.', 'Infarctus du myocarde dans les 24 premières heures chez les patients en situation hémodynamique stable.', 'Post-infarctus du myocarde chez les patients avec dysfonction ventriculaire gauche (fraction d’éjection £ à 40 %), et par ailleurs en l’absence de signe clinique d’insuffisance cardiaque.', 'Le traitement au long cours par le captopril améliore la survie à long terme, réduit le risque de récidive d’infarctus ainsi que le risque de développement d’une insuffisance cardiaque.', 'Néphropathie diabétique macroprotéinurique du diabète insulinodépendant.', 'Le traitement au long cours ralentit la progression de l’atteinte rénale.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être utilisé en cas de :', 'hypersensibilité au captopril, à tout autre inhibiteur de l’enzyme de conversion ou à l’un des excipients, mentionnés à la rubrique 6.1 ;', 'antécédent d’angio-œdème (œdème de Quincke) lié à la prise d’un inhibiteur de l’enzyme de conversion de l’angiotensine ;', 'angio-œdème héréditaire / idiopathique ;', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6) ;', 'utilisation concomitante avec un traitement par sacubitril/valsartan.', 'Le traitement par captopril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).', 'Ce médicament est généralement déconseillé dans les situations suivantes :', 'associations avec les diurétiques hyperkaliémiants, les sels de potassium, l''estramustine et le lithium (voir rubrique 4.5) ;', 'sténose bilatérale de l’artère rénale ou sur rein fonctionnellement unique ;', 'hyperkaliémie ;', 'grossesse (1er trimestre) ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Neutropénie/agranulocytose', 'Une neutropénie/agranulocytose, une thrombopénie et une anémie ont été rapportées chez les patients recevant des inhibiteurs de l''enzyme de conversion, dont le captopril.', 'La neutropénie survient rarement chez les patients à fonction rénale normale et ne présentant pas d''autres facteurs de risque.', 'Certains de ces patients ont présenté des infections graves qui, dans un petit nombre de cas, n''ont pas répondu à une antibiothérapie intensive.', 'Pendant le traitement, chaque patient doit recevoir comme consigne de signaler tout signe d''infection (par exemple : maux de gorge, fièvre) et une numération de la formule leucocytaire doit être effectuée.', 'Le captopril et tout autre traitement concomitant en cause (voir rubrique 4.5) seront interrompus si une neutropénie (granulocyte neutrophiles 3) est détectée ou suspectée.', 'Chez la plupart des patients, la numération des neutrophiles revient rapidement à la normale après arrêt du captopril.', 'Hypersensibilité/angio-œdème', 'Toutefois, dans de rares cas, l’angio-œdème sévère peut se développer après plusieurs mois ou années de traitement de longue durée par IEC.', 'Le traitement doit être interrompu immédiatement et le patient surveillé jusqu''à disparition de l''œdème.', 'Lorsque l''œdème n''intéresse que la face et les lèvres, l''évolution est en général régressive sans traitement, bien que les antihistaminiques aient été utilisés pour soulager les symptômes.', 'L''angio-œdème de la langue, de la glotte ou du larynx peut être mortel.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments hyperkaliémiants', 'L’association de ces médicaments majore le risque d’hyperkaliémie.', 'Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec le racécadotril, les inhibiteurs de mTOR (par exemple sirolimus, évérolimus, temsirolimus) et la vildagliptine peut entraîner un risque accru d’angio-œdème (voir rubrique 4.4).', 'Associations contre-indiquées', '+ Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubriques 4.3 et 4.4).', '+ Aliskiren chez le patient diabétique ou insuffisant rénal (DFG Risque d’hyperkaliémie, d’insuffisance rénale, d’augmentation de la morbi-mortalité cardio-vasculaire.', 'Associations déconseillées', '+ Aliskiren', 'Risque d’hyperkaliémie, d’insuffisance rénale, d’augmentation de la morbi-mortalité cardio-vasculaire.', '+ Diurétiques épargneurs de potassium, suppléments potassiques ou substituts de sel contenant du potassium']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent : troubles du sommeil.', 'Fréquents : altération du goût, sensations vertigineuses.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['La neutropénie survient rarement chez les patients à fonction rénale normale et ne présentant pas d''autres facteurs de risque.', 'Le traitement doit être interrompu immédiatement et le patient surveillé jusqu''à disparition de l''œdème.']);

  -- lisinopril (CIS 68748491)
  m := pg_temp.jp_matrice_by_norm('lisinopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’enzyme de conversion, code ATC : C09AA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle', 'Traitement de l''hypertension artérielle.', 'Insuffisance cardiaque', 'Traitement de l''insuffisance cardiaque symptomatique.', 'Infarctus du myocarde en phase aiguë', 'Traitement à court terme (6 semaines), chez les patients en situation hémodynamique stable, de l''infarctus du myocarde en phase aiguë, dans les 24 premières heures.', 'Complications rénales du diabète', 'Traitement de l''atteinte rénale chez l’hypertendu diabétique de type II présentant une néphropathie débutante (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, ou à l’un des excipients mentionnés à la rubrique 6.1 ou à tout autre inhibiteur de l''enzyme de conversion (IEC).', 'Antécédent d''angio-œdème associé à la prise d''un inhibiteur de l''enzyme de conversion.', 'Utilisation concomitante de LISINOPRIL ARROW avec un traitement par sacubitril/valsartan.', 'Le traitement par LISINOPRIL ARROW ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).', 'Angio-œdème héréditaire ou idiopathique.', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypotension symptomatique', 'Au cours du traitement de l''hypertension artérielle non compliquée, il est rare d''observer une hypotension symptomatique.', 'En cas d''insuffisance cardiaque, accompagnée ou non d''insuffisance rénale, des cas d''hypotension symptomatique ont été observés.', 'Ils sont plus fréquents en cas d''insuffisance cardiaque sévère (définie par l''utilisation de fortes doses de diurétiques de l''anse, la présence d''hyponatrémie ou d''insuffisance rénale fonctionnelle).', 'En cas de risque accru d''hypotension symptomatique, l''initiation du traitement et l''adaptation posologique doivent faire l''objet d''un suivi étroit.', 'En cas de survenue d''une hypotension, le patient doit être mis en position allongée et recevoir, si nécessaire, une perfusion IV de sérum salé.', 'Chez certains patients insuffisants cardiaques présentant une pression artérielle normale ou basse, LISINOPRIL ARROW peut provoquer une baisse supplémentaire de la pression artérielle.', 'Cet effet est prévisible et ne constitue généralement pas un motif d''arrêt du traitement.', 'Si l''hypotension devient symptomatique, une diminution de la posologie, ou un arrêt du traitement par LISINOPRIL ARROW peuvent être nécessaires.', 'Hypotension à la phase aiguë de l''infarctus du myocarde', 'Au cours des 3 premiers jours suivant l''infarctus, la posologie doit être diminuée si la pression artérielle systolique est inférieure ou égale à 120 mmHg.', 'La posologie d''entretien doit être réduite à 5 mg/jour, ou même temporairement à 2,5 mg/jour si la pression artérielle systolique est inférieure ou égale à 100 mmHg.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['+ Agents antihypertenseurs', '+ Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubriques 4.3 et 4.4).', '+ Diurétiques', 'Lorsqu’un diurétique est associé à LISINOPRIL ARROW, les effets antihypertenseurs sont en général additifs.', 'Le risque d’hypotension symptomatique peut être limité en arrêtant le diurétique avant de débuter le traitement par LISINOPRIL ARROW (voir rubriques 4.2 et 4.4).', '+ Potassium, diurétiques épargneurs de potassium, substituts de sel contenant du potassium et autres médicaments pouvant augmenter le taux de potassium sérique', 'Bien que la kaliémie demeure habituellement dans les limites de la normale, une hyperkaliémie peut survenir chez certains patients traités par LISINOPRIL ARROW.', 'Par conséquent, l’association de LISINOPRIL ARROW avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Si LISINOPRIL ARROW est associé à un diurétique hypokaliémiant, l’hypokaliémie provoquée par le diurétique peut être améliorée.', '+ Ciclosporine']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très rare : dépression médullaire, anémie, thrombocytopénie, leucopénie, neutropénie, agranulocytose (voir rubrique 4.4), anémie hémolytique, lymphadénopathie, maladie auto-immune.', 'Fréquence indéterminée : réactions anaphylactiques/anaphylactoïdes.', 'Fréquent : étourdissements, céphalées.', 'Peu fréquent : troubles de l’humeur, paresthésie, vertiges, troubles du goût, troubles du sommeil, hallucinations.']);

  -- perindopril (CIS 66286285)
  m := pg_temp.jp_matrice_by_norm('perindopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteurs de l’Enzyme de Conversion (IEC) non associés,code ATC: C09AA04');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension', 'Traitement de l’hypertension artérielle.', 'Maladie coronaire stable', 'Réduction du risque d’évènements cardiaques chez les patients ayant un antécédent d’infarctus du myocarde et/ou de revascularisation.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ou à un autre inhibiteur de l’enzyme de conversion (IEC),', 'Antécédent d’angioedème lié à la prise d’un IEC (voir rubrique 4.4),', 'Angioedème héréditaire ou idiopathique,', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6),', 'Traitement par circulation extra-corporelle entraînant un contact du sang avec des surfaces chargées négativement (voir rubrique 4.5),', 'Sténose bilatérale importante de l''artère rénale ou sténose de l''artère rénale sur rein fonctionnellement unique (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Maladie coronaire stable', 'Hypotension', 'Les IEC peuvent provoquer une chute de la pression artérielle.', 'Une hypotension symptomatique a été observée chez les patients ayant une insuffisance cardiaque, avec ou sans insuffisance rénale associée.', 'L’initiation du traitement et l’adaptation posologique devront être réalisées sous stricte surveillance médicale chez les patients à haut risque d’hypotension symptomatique (voir rubriques 4.2 et 4.8).', 'Si une hypotension se produit, le patient doit être placé en décubitus dorsal et, si nécessaire, recevoir une perfusion intraveineuse d’une solution de chlorure de sodium à 9 mg/mL (0,9 %).', 'Une diminution supplémentaire de la pression artérielle peut se produire avec PERINDOPRIL ARGININE BIOGARAN 10 mg chez certains patients en insuffisance cardiaque, ayant une pression artérielle normale ou basse.', 'Cet effet attendu ne nécessite généralement pas l’arrêt du traitement.', 'Si l’hypotension devient symptomatique, une diminution de la posologie ou l’arrêt de PERINDOPRIL ARGININE BIOGARAN 10 mg peut être nécessaire.', 'Sténose des valves aortique et mitrale / cardiomyopathie hypertrophique', 'Insuffisance rénale', 'En cas d’insuffisance rénale, (clairance de la créatinine Une hypotension secondaire à l’instauration du traitement par IEC peut conduire à des troubles de la fonction rénale chez les patients en insuffisance cardiaque.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubriques 4.3 et 4.4).', 'Le traitement par sacubitril/valsartan ne doit pas être débuté moins de 36 heures après la dernière dose de traitement contenant du périndopril.', 'Le traitement contenant du périndopril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir rubriques 4.3 et 4.4)', 'Médicaments entrainant une hyperkaliémie', 'Bien que la kaliémie reste généralement dans les limites de la normale, une hyperkaliémie peut se produire chez certains patients traités avec le PERINDOPRIL ARGININE BIOGARAN.', 'L’association de ces médicaments augmente le risque d’hyperkaliémie.', 'Par conséquent, l’association de PERINDOPRIL ARGININE BIOGARAN avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Associations contre-indiquées (voir rubrique 4.3)', '+ Aliskiren', 'Le risque d’hyperkaliémie, de dégradation de la fonction rénale et de la morbi-mortalité cardiovasculaire augmente chez les patients diabétiques ou insuffisants rénaux.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (³1/10); fréquent (³1/100, ³1/1000, ³1/10000,', 'Peu fréquent*']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’initiation du traitement et l’adaptation posologique devront être réalisées sous stricte surveillance médicale chez les patients à haut risque d’hypotension symptomatique (voir rubriques 4.2 et 4.8).', 'En cas d’insuffisance rénale, (clairance de la créatinine Une hypotension secondaire à l’instauration du traitement par IEC peut conduire à des troubles de la fonction rénale chez les patients en insuffisance cardiaque.']);

  -- hydroquinidine (CIS 60518136)
  m := pg_temp.jp_matrice_by_norm('hydroquinidine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTI-ARYTHMIQUE CLASSE IA, code ATC : C01BA13.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Le chlorhydrate d’hydroquinidine NE DOIT JAMAIS ÊTRE UTILISÉ dans les situations suivantes :', 'hypersensibilité à l’hydroquinidine ou à la quinidine (voir rubrique 4.4) ou à l’un des excipients mentionnés à la rubrique 6.1,', 'bloc auriculo-ventriculaire non appareillé,', 'bloc de branche complet, autres troubles marqués de la conduction intraventriculaire,', 'troubles de l’automatisme sinusal (maladie de l’oreillette) non appareillés,', 'troubles du rythme de l’intoxication digitalique,', 'torsades de pointes,', 'QT long,', 'insuffisance cardiaque,', 'association avec les médicaments torsadogènes (sauf antiparasitaires, neuroleptiques et méthadone) :', 'o les antiarythmiques de classe Ia (quinidine, disopyramide),', 'o les antiarythmiques de classe III (amiodarone, sotalol, dofétilide, ibutilide),']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'L’incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'Comme pour les autres antiarythmiques de classe I, il n’existe pas d’essai contrôlé mettant en évidence un effet bénéfique de l’hydroquinidine en termes de survie ou de mort subite.', 'Hypersensibilité/idiosyncrasie', 'L’éventualité d’accidents gravissimes en cas d’hypersensibilité (en particulier arrêt cardiocirculatoire inopiné) conduit à tester la sensibilité des patients avant la mise en route d’un traitement par l’hydroquinidine :', 'une gélule test est administrée,', 'par contre, si les modifications électrocardiographiques ne se produisent qu’après 48 heures (et en l’absence des autres signes décrits ci-dessus), il suffira de diminuer les doses,', 'la survenue d’une fièvre inexpliquée doit conduire à la réalisation d’un bilan hépatique.', 'Le chlorhydrate d’hydroquinidine EST GÉNÉRALEMENT DÉCONSEILLÉ dans les situations suivantes :', 'grossesse, allaitement,', 'myasthénie,', 'Ce médicament contient du saccharose.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments antiarythmiques', 'De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l’ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d’effets indésirables cardiaques.', 'Médicaments susceptibles de donner des torsades de pointes', 'Ce trouble du rythme cardiaque grave peut être provoqué par un certain nombre de médicaments, antiarythmiques ou non.', 'L''hypokaliémie (cf. médicaments hypokaliémiants) est un facteur favorisant, de même que la bradycardie (cf. médicaments bradycardisants) ou un allongement préexistant de l''intervalle QT, congénital ou acquis.', 'Les médicaments à l’origine de cet effet indésirable sont notamment les antiarythmiques de classe Ia et III, et certains neuroleptiques.', 'D''autres molécules n’appartenant pas à ces classes sont également en cause.', 'Pour le dolasétron, l’érythromycine, la spiramycine et la vincamine, seules les formes administrées par voie intraveineuse sont concernées par cette interaction.', 'L''utilisation d''un médicament torsadogène avec un autre médicament torsadogène est contre-indiquée en règle générale.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Classification des effets indésirables selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100,', 'Très Fréquent', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'la survenue d’une fièvre inexpliquée doit conduire à la réalisation d’un bilan hépatique.']);

END
$mig$;
